from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import ClinicalCase, PsychiatricEvaluationCase
from .serializers import ClinicalCasePolymorphicSerializer

class PatientCaseDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, case_id):
        try:
            case = ClinicalCase.objects.get(id=case_id)
        except ClinicalCase.DoesNotExist:
            return Response({'detail': 'Case file not found'}, status=status.HTTP_404_NOT_FOUND)

        if not request.user.is_clinical_staff:
            return Response({'detail': 'Clinical staff access only'}, status=status.HTTP_403_FORBIDDEN)

        if isinstance(case, PsychiatricEvaluationCase):
            # Enforce dedicated psychiatric authorization
            if not (request.user == case.attending_psychiatrist or case.has_patient_consent_for(request.user)):
                return Response({'detail': 'Explicit psychiatric consent required to access psychotherapy records'}, status=status.HTTP_403_FORBIDDEN)

        serializer = ClinicalCasePolymorphicSerializer(case)
        return Response(serializer.data)
